import { CodeGenerator, Names, type Block, type Workspace } from 'blockly';
import { LB_ARITH_OPS, LB_COLORS, LB_COMPARE_OPS, LB_LEDS, type LbColorId } from './blocks';

// Arduino code of the Leanbot blocks, character for character what Pythaverse's editor
// (ide.pythaverse.space/lbeditor, generator 2024-09-15) prints for the matching block: the same
// spacing, parentheses, blank lines and loop counter names. Checked against code generated by
// that editor in leanbot.test.ts (fixtures/pythaverse-*.ino).

/** Operator precedence of Pythaverse's Arduino generator (Blockly.Arduino.ORDER_*). */
export const Order = {
  ATOMIC: 0,
  UNARY_PREFIX: 2,
  MULTIPLICATIVE: 3,
  ADDITIVE: 4,
  RELATIONAL: 6,
  EQUALITY: 7,
  LOGICAL_AND: 11,
  LOGICAL_OR: 12,
  UNARY_NEGATION: 16,
  NONE: 99,
} as const;

const MARK_START = '\u0001';
const MARK_END = '\u0002';

type Generated = string | [string, number] | null;
type BlockGenerator = (block: Block, gen: ArduinoGenerator) => Generated;

const colorOf = (block: Block) =>
  LB_COLORS.find((c) => c.id === (block.getFieldValue('COLOR') as LbColorId)) ?? LB_COLORS[0];

/** `String(Number(x))`, like Pythaverse's `math_number` (`parseFloat`). */
function numberText(block: Block, field: string): string {
  return String(Number(block.getFieldValue(field)));
}

/** A number field read as a value: negative numbers bind like unary minus. */
function numberValue(block: Block, field: string): [string, number] {
  const text = numberText(block, field);
  return [text, Number(text) >= 0 ? Order.ATOMIC : Order.UNARY_NEGATION];
}

/** Pythaverse's mission blocks print their body one indent less: missions do not nest code. */
function missionBody(block: Block, gen: ArduinoGenerator): string {
  return gen.statementToCode(block, 'BODY').substring(2).replaceAll('\n  ', '\n');
}

/** Blockly's `controls_whileUntil` in UNTIL mode: `!x` for a bare word, else `!(…)`. */
function negate(condition: string): string {
  return /^\w+$/.test(condition) ? `!${condition}` : `!(${condition})`;
}

const FOR_BLOCK: Readonly<Record<string, BlockGenerator>> = {
  lb_mission_touch: (block, gen) =>
    `LbMission.begin(${String(block.getFieldValue('COMBO'))});\n${missionBody(block, gen)}LbMission.end();\n`,
  lb_mission_now: (block, gen) =>
    `LbMission.begin(0);\n${missionBody(block, gen)}LbMission.end();\n`,
  lb_wait: (block) =>
    block.getFieldValue('UNIT') === 'SEC'
      ? `LbDelay(${numberText(block, 'N')} * 1000);\n`
      : `LbDelay(${numberText(block, 'N')});\n`,
  lb_comment: (block) => `\n// ${String(block.getFieldValue('TEXT'))}\n`,
  lb_run: (block) =>
    `LbMotion.runLRrpm(${numberText(block, 'LEFT')}, ${numberText(block, 'RIGHT')});\n`,
  lb_go: (block) =>
    block.getFieldValue('UNIT') === 'CM'
      ? `LbMotion.waitDistanceMm(${numberText(block, 'N')} * 10);\n`
      : `LbMotion.waitDistanceMm(${numberText(block, 'N')});\n`,
  lb_turn: (block) => `LbMotion.waitRotationDeg(${numberText(block, 'N')});\n`,
  lb_stop: () => 'LbMotion.stopAndWait();\n',
  lb_gripper_open: () => 'LbGripper.open();\n',
  lb_gripper_close: () => 'LbGripper.close();\n',
  lb_gripper_to: (block) => `LbGripper.moveTo(${numberText(block, 'N')});\n`,
  lb_gripper_to_lr: (block) =>
    `LbGripper.moveToLR(${numberText(block, 'LEFT')}, ${numberText(block, 'RIGHT')}, ${numberText(block, 'MS')});\n`,
  lb_led_set: (block) =>
    `LbRGB[${String(block.getFieldValue('LED'))}] = CRGB::${colorOf(block).crgb};\n`,
  lb_led_fill: (block) => {
    const leds = LB_LEDS.filter((led) => block.getFieldValue(led) === 'TRUE');
    return `LbRGB.fillColor(${colorOf(block).hex}, BITMAP(${leds.join(', ')}));\n`;
  },
  lb_led_clear: () => 'LbRGB.clear();\n',
  lb_led_show: () => 'LbRGB.show();\n',
  lb_tone: (block) => {
    const ms = numberText(block, 'MS');
    return `Leanbot.tone(${numberText(block, 'HZ')}, ${ms});\nLbDelay(${ms});\n`;
  },
  lb_touch_wait: (block) => `while (LbTouch.read(${String(block.getFieldValue('PAD'))}) == LOW);\n`,
  lb_touch_is: (block) => [
    `(LbTouch.read(${String(block.getFieldValue('PAD'))}) == HIGH)`,
    Order.ATOMIC,
  ],
  lb_ping: () => ['Leanbot.pingCm()', Order.ATOMIC],
  lb_object_near: (block) => [
    `Leanbot.pingCm() <= ${String(Math.round(Number(block.getFieldValue('CM'))))}`,
    Order.RELATIONAL,
  ],
  lb_irline_read: () => 'LbIRLine.read();\n',
  lb_irline_black: () => ['LbIRLine.isBlackDetected()', Order.ATOMIC],
  // Pythaverse: `logic_compare(LbIRLine.value, LbIRLine.state)`; the state is a 4-bit number,
  // outer left eye (2L) the highest bit.
  lb_irline_is: (block) => {
    const bits = ['E2L', 'E0L', 'E1R', 'E3R'].map((f) => (block.getFieldValue(f) === 'B' ? 1 : 0));
    const state = bits.reduce((acc: number, bit) => acc * 2 + bit, 0);
    return [`(LbIRLine.value() == ${String(state)})`, Order.EQUALITY];
  },
  lb_irline_show: (block) => `LbIRLine.displayOnRGB(${colorOf(block).hex});\n`,
  lb_if: (block, gen) =>
    `if (${gen.valueToCode(block, 'COND', Order.NONE) || 'false'}) {\n${gen.statementToCode(block, 'DO')}}\n`,
  lb_if_else: (block, gen) =>
    `if (${gen.valueToCode(block, 'COND', Order.NONE) || 'false'}) {\n${gen.statementToCode(block, 'DO')}} else {\n${gen.statementToCode(block, 'ELSE')}}\n`,
  lb_compare: (block, gen) => {
    const op = LB_COMPARE_OPS[block.getFieldValue('OP') as keyof typeof LB_COMPARE_OPS];
    const order = op === '==' || op === '!=' ? Order.EQUALITY : Order.RELATIONAL;
    const a = gen.valueToCode(block, 'A', order) || '0';
    const b = gen.valueToCode(block, 'B', order) || '0';
    return [`(${a} ${op} ${b})`, order];
  },
  lb_and_or: (block, gen) => {
    const and = block.getFieldValue('OP') === 'AND';
    const order = and ? Order.LOGICAL_AND : Order.LOGICAL_OR;
    let a = gen.valueToCode(block, 'A', order);
    let b = gen.valueToCode(block, 'B', order);
    if (!a && !b) {
      a = 'false';
      b = 'false';
    } else {
      a ||= and ? 'true' : 'false';
      b ||= and ? 'true' : 'false';
    }
    return [`${a} ${and ? '&&' : '||'} ${b}`, order];
  },
  lb_not: (block, gen) => [
    `!${gen.valueToCode(block, 'A', Order.UNARY_PREFIX) || 'false'}`,
    Order.UNARY_PREFIX,
  ],
  lb_bool: (block) => [block.getFieldValue('BOOL') === 'TRUE' ? 'true' : 'false', Order.ATOMIC],
  // The counter is named after the body is generated, so an inner loop takes `count` and the
  // outer one `count2`, as in Pythaverse.
  lb_repeat: (block, gen) => {
    const branch = gen.statementToCode(block, 'DO');
    const counter = gen.distinctName('count');
    return `for (int ${counter} = 0; ${counter} < ${numberText(block, 'TIMES')}; ${counter}++) {\n${branch}}\n\n`;
  },
  lb_repeat_while: (block, gen) =>
    `while (${gen.valueToCode(block, 'COND', Order.NONE) || 'false'}) {\n${gen.statementToCode(block, 'DO')}}\n\n`,
  lb_repeat_until: (block, gen) =>
    `while (${negate(gen.valueToCode(block, 'COND', Order.NONE) || 'false')}) {\n${gen.statementToCode(block, 'DO')}}\n\n`,
  lb_forever: (block, gen) => `while (true) {\n${gen.statementToCode(block, 'DO')}}\n\n`,
  lb_number: (block) => numberValue(block, 'N'),
  lb_arith: (block, gen) => {
    const op = LB_ARITH_OPS[block.getFieldValue('OP') as keyof typeof LB_ARITH_OPS];
    const order = op === '+' || op === '-' ? Order.ADDITIVE : Order.MULTIPLICATIVE;
    const a = gen.valueToCode(block, 'A', order) || '0';
    const b = gen.valueToCode(block, 'B', order) || '0';
    return [`${a} ${op} ${b}`, order];
  },
};

class ArduinoGenerator extends CodeGenerator {
  constructor() {
    super('LeanbotArduino');
    // Pythaverse keeps `a && b && c` and `a || b || c` flat.
    this.ORDER_OVERRIDES = [
      [Order.LOGICAL_AND, Order.LOGICAL_AND],
      [Order.LOGICAL_OR, Order.LOGICAL_OR],
    ];
    for (const [type, fn] of Object.entries(FOR_BLOCK)) {
      this.forBlock[type] = (block) => fn(block, this);
    }
  }

  override init(workspace: Workspace): void {
    super.init(workspace);
    this.nameDB_ = new Names('');
    this.nameDB_.setVariableMap(workspace.getVariableMap());
  }

  distinctName(name: string): string {
    if (this.nameDB_ === undefined) throw new Error('generator.init(workspace) was not called');
    return this.nameDB_.getDistinctName(name, Names.NameType.VARIABLE);
  }

  /** Marks the start of each statement with its block id (stripped again by `toArduino`). */
  override injectId(msg: string, block: Block): string {
    return msg.replace(/%1/g, () => block.id);
  }

  override scrub_(block: Block, code: string, thisOnly?: boolean): string {
    const next = block.nextConnection?.targetBlock();
    if (thisOnly === true || !next) return code;
    const rest = this.blockToCode(next);
    return typeof rest === 'string' ? code + rest : code;
  }
}

const generator = new ArduinoGenerator();

/** The generated program and the line (0-based) each statement block starts on. */
export interface ArduinoProgram {
  code: string;
  lineOf: ReadonlyMap<string, number>;
}

/**
 * The whole sketch for `workspace`, as Pythaverse writes it minus its 3-line "Generated … at
 * <time>" header (a clock would make the code differ on every call). Value blocks lying loose
 * on the workspace are left out; Pythaverse would print them as stray expressions.
 */
export function toArduino(workspace: Workspace): ArduinoProgram {
  generator.STATEMENT_PREFIX = `${MARK_START}%1${MARK_END}`;
  generator.init(workspace);
  const stacks = workspace
    .getTopBlocks(true)
    .filter((block) => !block.outputConnection)
    .map((block) => generator.blockToCode(block))
    .filter((code): code is string => typeof code === 'string');
  const body = stacks.join('\n');
  let code: string;
  if (body.length === 0) {
    code = 'void setup() {\n}\n\nvoid loop() {\n}';
  } else {
    const loop = `void loop() {\n  ${body.replace(/\n/g, '\n  ')}`.slice(0, -2);
    code = `#include <Leanbot.h>\n\nvoid setup() {\n  Leanbot.begin();\n}\n\n${loop}}`;
  }
  // Blockly's workspaceToCode: no blank lines at the start, no trailing spaces.
  code = code.replace(/^\s+\n/, '').replace(/[ \t]+\n/g, '\n');
  return stripMarks(code);
}

/** Removes the block id marks; a mark on an empty line belongs to the next line with code. */
function stripMarks(marked: string): ArduinoProgram {
  const lineOf = new Map<string, number>();
  const pending: string[] = [];
  const marks = new RegExp(`${MARK_START}([^${MARK_END}]*)${MARK_END}`, 'g');
  const lines = marked.split('\n').map((line, index) => {
    for (const match of line.matchAll(marks)) pending.push(match[1] ?? '');
    const text = line.replace(marks, '');
    if (text.trim().length > 0) {
      for (const id of pending) if (!lineOf.has(id)) lineOf.set(id, index);
      pending.length = 0;
    }
    return text.trimEnd();
  });
  return { code: lines.join('\n'), lineOf };
}
